// Debounce: run once, after the burst ends
function debounce(fn, wait) {
  let timer = null;
  const debounced = (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), wait);
  };
  debounced.cancel = () => clearTimeout(timer);
  return debounced;
}

// Throttle: run at most once per window (leading + trailing)
function throttle(fn, wait) {
  let last = 0, timer = null;
  const throttled = (...args) => {
    const now = Date.now();
    const remaining = wait - (now - last);
    if (remaining <= 0) {
      if (timer) { clearTimeout(timer); timer = null; }
      fn(...args);
      last = now;
    } else if (!timer) {
      timer = setTimeout(() => { fn(...args); last = Date.now(); timer = null; }, remaining);
    }
  };
  throttled.cancel = () => { clearTimeout(timer); timer = null; };
  return throttled;
}

// Usage:
const onSearch = debounce((q) => fetchResults(q), 300);
const onScroll = throttle(() => updateParallax(), 100);

// ❌ React without cleanup: pending call fires after unmount
useEffect(() => {
  window.addEventListener('scroll', onScroll);
  return () => {
    window.removeEventListener('scroll', onScroll);
    onScroll.cancel();                    // ✅ drop pending trailing call
  };
}, [onScroll]);

